        {section==='rewards'&&<section className={`${card} mb-4`}><h2 className="mb-4 font-black">{t.rewardBoxes}</h2><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{Object.entries(lootTables||{}).map(([boxId,table])=><article key={boxId} className="rounded-xl border border-white/10 bg-[#100f1a] p-3"><h3 className="mb-2 font-bold text-violet-200">{boxId.replaceAll('_',' ')}</h3><p className="text-xs text-slate-400">{t.guaranteed}</p><div className="mb-2 space-y-1">{(table.guaranteed||[]).map((drop,index)=><div key={`${drop.type}-${index}`} className="flex justify-between gap-2 text-sm"><span>{drop.name||drop.type}</span><span className="text-emerald-300">×{Array.isArray(drop.qty)?`${drop.qty[0]}–${drop.qty[1]}`:drop.qty}</span></div>)}</div>{table.rolls>0&&<p className="mb-1 text-xs text-slate-400">{t.rolls}: {table.rolls}</p>}<p className="text-xs text-slate-400">{t.bonus}</p><div className="space-y-1">{(table.bonus||[]).map((drop,index)=><div key={`${drop.type}-${index}`} className="flex justify-between gap-2 text-sm"><span>{drop.name||drop.type}</span><span className="text-cyan-300">×{Array.isArray(drop.qty)?`${drop.qty[0]}–${drop.qty[1]}`:drop.qty}{drop.weight!=null?` · ${drop.weight}%`:''}</span></div>)}</div></article>)}</div>{!Object.keys(lootTables||{}).length&&<p className="text-slate-500">{t.noData}</p>}</section>}
